import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Custom CUDA kernel for fused ReLU + MaxPool2d
relu_max_pool_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void relu_max_pool2d_kernel(const float* input, float* output, 
                                      int batch_size, int channels, 
                                      int input_height, int input_width, 
                                      int pool_size, int stride) {
    int output_height = (input_height - pool_size) / stride + 1;
    int output_width = (input_width - pool_size) / stride + 1;

    int n = blockIdx.x; 
    int c = blockIdx.y; 
    int h_out = blockIdx.z / output_width; 
    int w_out = blockIdx.z % output_width; 

    if (n >= batch_size || c >= channels || h_out >= output_height || w_out >= output_width) 
        return;

    int h_start = h_out * stride;
    int w_start = w_out * stride;
    int h_end = h_start + pool_size;
    int w_end = w_start + pool_size;

    float max_val = -INFINITY;
    for (int h = h_start; h < h_end; ++h) {
        for (int w = w_start; w < w_end; ++w) {
            int idx = n*channels*input_height*input_width + 
                      c*input_height*input_width + 
                      h*input_width + w;
            float val = input[idx];
            val = val > 0.0f ? val : 0.0f;
            max_val = fmaxf(max_val, val);
        }
    }

    int out_idx = n*channels*output_height*output_width + 
                  c*output_height*output_width + 
                  h_out*output_width + w_out;
    output[out_idx] = max_val;
}

torch::Tensor relu_max_pool2d_cuda(torch::Tensor input, int pool_size, int stride) {
    int batch_size = input.size(0);
    int channels = input.size(1);
    int input_h = input.size(2);
    int input_w = input.size(3);

    int output_h = (input_h - pool_size)/stride + 1;
    int output_w = (input_w - pool_size)/stride + 1;

    auto output = torch::zeros({batch_size, channels, output_h, output_w}, input.options());

    dim3 blocks(batch_size, channels, output_h * output_w);
    relu_max_pool2d_kernel<<<blocks, 1>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        channels,
        input_h,
        input_w,
        pool_size,
        stride
    );

    return output;
}
"""

relu_max_pool_cpp = "torch::Tensor relu_max_pool2d_cuda(torch::Tensor input, int pool_size, int stride);"

# Custom CUDA kernel for fused Linear + ReLU
linear_relu_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void linear_relu_kernel(const float* input, const float* weight, const float* bias,
                                   float* output, 
                                   int in_features, int out_features, int batch_size) {
    int row = blockIdx.x * blockDim.x + threadIdx.x;
    int col = blockIdx.y * blockDim.y + threadIdx.y;

    if (row < batch_size && col < out_features) {
        float sum = 0.0f;
        for (int k = 0; k < in_features; ++k) {
            sum += input[row*in_features + k] * weight[col*in_features + k];
        }
        sum += bias[col];
        output[row*out_features + col] = sum > 0.0f ? sum : 0.0f;
    }
}

torch::Tensor linear_relu_cuda(torch::Tensor input, torch::Tensor weight, torch::Tensor bias) {
    int batch_size = input.size(0);
    int in_feat = input.size(1);
    int out_feat = weight.size(0);

    auto output = torch::zeros({batch_size, out_feat}, input.options());

    dim3 block(16, 16);
    dim3 grid((batch_size + block.x - 1)/block.x, (out_feat + block.y - 1)/block.y);

    linear_relu_kernel<<<grid, block>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        in_feat,
        out_feat,
        batch_size
    );

    return output;
}
"""

linear_relu_cpp = "torch::Tensor linear_relu_cuda(torch::Tensor input, torch::Tensor weight, torch::Tensor bias);"

# Load CUDA extensions
relu_max_pool_ext = load_inline(
    name='relu_max_pool',
    cpp_sources=relu_max_pool_cpp,
    cuda_sources=relu_max_pool_source,
    functions=['relu_max_pool2d_cuda'],
    verbose=False
)

linear_relu_ext = load_inline(
    name='linear_relu',
    cpp_sources=linear_relu_cpp,
    cuda_sources=linear_relu_source,
    functions=['linear_relu_cuda'],
    verbose=False
)

class ModelNew(nn.Module):
    def __init__(self, num_classes):
        super(ModelNew, self).__init__()
        self.conv1 = nn.Conv2d(1, 6, kernel_size=5)
        self.conv2 = nn.Conv2d(6, 16, kernel_size=5)
        self.fc1 = nn.Linear(16*5*5, 120)
        self.fc2 = nn.Linear(120, 84)
        self.fc3 = nn.Linear(84, num_classes)

    def forward(self, x):
        # Conv1 + ReLU + MaxPool
        x = relu_max_pool_ext.relu_max_pool2d_cuda(self.conv1(x), 2, 2)
        # Conv2 + ReLU + MaxPool
        x = relu_max_pool_ext.relu_max_pool2d_cuda(self.conv2(x), 2, 2)

        x = x.view(-1, 16*5*5)

        # FC1 + ReLU
        x = linear_relu_ext.linear_relu_cuda(x, self.fc1.weight, self.fc1.bias)
        # FC2 + ReLU
        x = linear_relu_ext.linear_relu_cuda(x, self.fc2.weight, self.fc2.bias)
        # FC3
        x = self.fc3(x)

        return x
